// Prepare log entry
const input = $('When Executed by Another Workflow').first().json;
const userResult = $input.first().json;

const userId = userResult?.id || null;

return {
  userId: userId,
  phoneNumber: input.phoneNumber,
  direction: 'inbound',
  messageType: 'text',
  messageContent: input.messageContent || '',
  whatsappMessageId: input.messageId || null,
  status: input.success !== false ? 'sent' : 'failed',
  errorMessage: input.error || null
};

// Prepare log entry
const input = $('When Executed by Another Workflow').item.json;
const userResult = $('Get User ID').item.json;
const userId = userResult?.id || null;

return {
  userId: userId,
  phoneNumber: input.phoneNumber,
  direction: 'outbound',
  messageType: 'text',
  messageContent: input.outboundMessage || '',
  whatsappMessageId: input.outboundMessageId || null,
  status: input.success !== false ? 'sent' : 'failed',
  errorMessage: input.error || null
};

// Return log result
const logResult = $input.item.json;

return {
  logged: true,
  logId: logResult?.id
};

const input = $input.first().json;

return [{
  json: {
    userId: input.user?.id || null,
    consultationId: input.user?.current_consultation_id || null,
    direction: 'inbound', // Always inbound for user messages
    messageType: input.messageType,
    content: input.messageContent,
    whatsappMessageId: input.messageId,
    metadata: {
      rawMessage: input.rawMessage,
      timestamp: input.timestamp,
      contactName: input.contactName
    }
  }
}];

